		// Đảm bảo hệ thống menu chỉ khởi tạo 1 lần
		if (!this.isMenuInit) {
		    this.isMenuInit = true;
		    var _this = this;
		
		    // Bật bắt sự kiện Hover cho HTML5 (Rất quan trọng cho Menu)
		    if (_this.stage) _this.stage.enableMouseOver(10);
		
		    // =============================================================
		    // 0. CẤU HÌNH THÔNG SỐ GIỐNG HỆT MENUITEM.AS
		    // =============================================================
		    var MIN_WIDTH = 160;    
		    var MAX_WIDTH = 320;    
		    var BASE_HEIGHT = 32;   
		    var CORNER_RADIUS = 4;  
		    var ITEM_GAP = 4;       
		    var PADDING = 5;
		
		    var COLOR_TEXT = "#F3F4F6";
		    var COLOR_TEXT_HOVER = "#00FFFF"; 
		    var COLOR_BORDER = "rgba(75,85,99,0.5)"; // 0x4B5563
		
		    // =============================================================
		    // 1. CLASS GIẢ LẬP: MENU ITEM 
		    // =============================================================
		    function createMenuItem(label, action) {
		        var item = new createjs.Container();
		        item.name = "menuItem"; // ĐỊNH DANH ĐỂ VƯỢT LỚP CHẶN CLICK
		        item.action = action;
		        item.subItems = [];
		        item.parentItem = null;
		        item.isSubMenuOpen = false;
		
		        item.requiredWidth = MIN_WIDTH; 
		        item.actualWidth = MIN_WIDTH;   
		        item.actualHeight = BASE_HEIGHT;
		
		        var bg = new createjs.Shape();
		        
		        // Font chữ chuẩn Roboto/Arial
		        var tf = new createjs.Text(label, "bold 13px Roboto, Arial, sans-serif", COLOR_TEXT);
		        tf.x = 18;
		        tf.lineHeight = 18; // Tương đương leading = 5
		
		        // THUẬT TOÁN ĐO LƯỜNG TEXT (Y hệt AS3)
		        var rawWidth = tf.getMeasuredWidth() + 50; 
		        
		        if (rawWidth > MAX_WIDTH) {
		            item.requiredWidth = MAX_WIDTH;
		            tf.lineWidth = MAX_WIDTH - 40; // Bật WordWrap
		            item.actualHeight = tf.getMeasuredHeight() + 14; 
		            if (item.actualHeight < BASE_HEIGHT) item.actualHeight = BASE_HEIGHT;
		            tf.y = (item.actualHeight - tf.getMeasuredHeight()) / 2 - 2;
		        } else {
		            item.requiredWidth = Math.max(MIN_WIDTH, rawWidth);
		            tf.lineWidth = null; 
		            tf.y = 7; // Căn giữa cho 1 dòng
		        }
		
		        item.addChild(bg, tf);
		
		        var subMenuContainer = new createjs.Container();
		        subMenuContainer.visible = false;
		        item.addChild(subMenuContainer);
		        item.subMenuContainer = subMenuContainer;
		
		        item.cursor = "pointer";
		
		        // HÀM VẼ GIAO DIỆN NÚT (Gradient & Viền)
		        item.drawState = function(isHover) {
		            bg.graphics.clear();
		            var w = item.actualWidth;
		            var h = item.actualHeight;
		            var r = CORNER_RADIUS;
		
		            // Vùng đệm bắt chuột (hit area) trong suốt
		            bg.graphics.beginFill("rgba(0,0,0,0.01)")
		               .drawRect(-ITEM_GAP, -ITEM_GAP/2, w + (ITEM_GAP * 2), h + ITEM_GAP)
		               .endFill();
		
		            if (isHover) {
		                bg.graphics.setStrokeStyle(1.5).beginStroke("rgba(0,229,255,0.8)"); // 0x00E5FF
		                bg.graphics.beginLinearGradientFill(["#374151", "#1F2937"], [0, 1], 0, 0, 0, h);
		                bg.graphics.drawRoundRect(0, 0, w, h, r, r).endFill().endStroke();
		
		                // Cạnh viền trái Cyan
		                bg.graphics.beginFill("#00FFFF").drawRoundRect(0, 0, 5, h, r/2, r/2).endFill();
		            } else {
		                bg.graphics.setStrokeStyle(1).beginStroke(COLOR_BORDER);
		                bg.graphics.beginLinearGradientFill(["#2A3441", "#151D28"], [0, 1], 0, 0, 0, h);
		                bg.graphics.drawRoundRect(0, 0, w, h, r, r).endFill().endStroke();
		                
		                // Vệt sáng mảnh ở mép trên (Mô phỏng 3D)
		                bg.graphics.setStrokeStyle(1).beginStroke("rgba(255,255,255,0.15)");
		                bg.graphics.moveTo(r, 1).lineTo(w - r, 1).endStroke();
		            }
		            
		            // Vẽ mũi tên tam giác nếu có menu con
		            if (item.subItems.length > 0) {
		                bg.graphics.beginFill(isHover ? "#00FFFF" : "#9CA3AF");
		                bg.graphics.moveTo(w - 18, h / 2 - 3)
		                           .lineTo(w - 14, h / 2)
		                           .lineTo(w - 18, h / 2 + 3)
		                           .endFill();
		            }
		        };
		
		        item.updateSize = function(newWidth) {
		            item.actualWidth = newWidth;
		            if (!tf.lineWidth && tf.getMeasuredWidth() > newWidth - 40) {
		                tf.lineWidth = newWidth - 40; // Ép bọc chữ nếu cần
		            }
		            item.drawState(false);
		        };
		
		        item.addSubItem = function(childItem) {
		            childItem.parentItem = item;
		            item.subItems.push(childItem);
		            subMenuContainer.addChild(childItem);
		            item.repositionSubMenus();
		        };
		
		        // HÀM VẼ TẤM NỀN TRẮNG CHO MENU CẤP 2 (Giống hệt AS3)
		        item.repositionSubMenus = function() {
		            if (item.subItems.length === 0) return;
		            var maxChildWidth = MIN_WIDTH;
		            for (var i = 0; i < item.subItems.length; i++) {
		                if (item.subItems[i].requiredWidth > maxChildWidth) maxChildWidth = item.subItems[i].requiredWidth;
		            }
		
		            var currentY = PADDING;
		            for (var j = 0; j < item.subItems.length; j++) {
		                var child = item.subItems[j];
		                child.updateSize(maxChildWidth);
		                child.x = PADDING;
		                child.y = currentY;
		                currentY += child.actualHeight + ITEM_GAP;
		            }
		
		            var panelW = maxChildWidth + (PADDING * 2);
		            var panelH = currentY + PADDING - ITEM_GAP;
		
		            var bgShape = subMenuContainer.getChildByName("bgShape");
		            if (!bgShape) {
		                bgShape = new createjs.Shape();
		                bgShape.name = "bgShape";
		                subMenuContainer.addChildAt(bgShape, 0); // Đẩy xuống dưới cùng
		            }
		            
		            bgShape.graphics.clear()
		                .beginFill("#FFFFFF")
		                .setStrokeStyle(1).beginStroke("rgba(75,85,99,0.2)")
		                .drawRoundRect(0, 0, panelW, panelH, 6, 6)
		                .endFill().endStroke();
		        };
		
		        item.toggleSubMenu = function(show) {
		            item.isSubMenuOpen = show;
		            subMenuContainer.visible = show;
		            if (show) {
		                subMenuContainer.x = item.actualWidth + ITEM_GAP;
		                subMenuContainer.y = -5; 
		            }
		        };
		
		        item.closeEntireTree = function() {
		            item.toggleSubMenu(false);
		            if (item.parentItem != null) item.parentItem.closeEntireTree();
		        };
		
		        // --- TƯƠNG TÁC SỰ KIỆN (Dùng rollover/rollout thay vì mouseover) ---
		        // --- TƯƠNG TÁC SỰ KIỆN (ĐÃ FIX LỖI LIỆT NÚT CANVAS) ---
		        item.on("rollover", function(e) {
		            item.drawState(true);
		            tf.color = COLOR_TEXT_HOVER;
		            if (item.subItems.length > 0) item.toggleSubMenu(true);
		        });
		
		        item.on("rollout", function(e) {
		            item.drawState(false);
		            tf.color = COLOR_TEXT;
		            if (item.subItems.length > 0) item.toggleSubMenu(false);
		        });
		
		        // 🔥 DÙNG MOUSEDOWN THAY VÌ CLICK ĐỂ CHỐNG TRƯỢT 100% 🔥
		        item.on("mousedown", function(e) {
		            e.nativeEvent.stopPropagation();
		            e.stopPropagation();
		
		            if (item.subItems.length > 0) {
		                // Hỗ trợ màn hình cảm ứng: Bấm vào Menu cha sẽ tự bung Menu con
		                item.toggleSubMenu(!item.isSubMenuOpen);
		            } else if (item.action !== "") {
		                console.log("🎯 BẠN VỪA CHỌN BÀI HỌC MÃ LÀ: [" + item.action + "]");
		                
		                // Radar dò tìm Engine Kịch Bản (Cực kỳ an toàn)
		                var engineRoot = (typeof exportRoot !== "undefined") ? exportRoot : _this;
		                
		                if (typeof engineRoot.playScenarioWithLog === "function") {
		                    console.log("🚀 Đang kích hoạt Engine Kịch bản...");
		                    engineRoot.playScenarioWithLog(item.action);
		                } else if (typeof engineRoot[item.action] === "function") {
		                    console.log("🚀 Đang kích hoạt hàm Function lẻ...");
		                    engineRoot[item.action]();
		                } else {
		                    console.error("❌ CHẾT MÁY: Không tìm thấy hàm playScenarioWithLog ở root!");
		                }
		                
		                // Đóng menu sau khi đã chọn xong
		                item.closeEntireTree();
		                if (window.menuBarRoot) window.menuBarRoot.visible = false; 
		            } else {
		                console.warn("⚠️ Nút Menu này bị trống, không có lệnh Action từ Excel!");
		            }
		        });
		        return item;
		    }
		
		    // =============================================================
		    // 2. HÀM DỰNG MENU TỔNG & VẼ NỀN CẤP 1
		    // =============================================================
		    var rootItemsList = [];
		    
		    function buildMenu(data, container) {
		        var maxRootWidth = 0; 
		        
		        for (var i = 0; i < data.length; i++) {
		            var node = data[i];
		            var item = createMenuItem(node.label, node.action ? node.action : "");
		            rootItemsList.push(item);
		            container.addChild(item);
		            if (item.requiredWidth > maxRootWidth) maxRootWidth = item.requiredWidth;
		            if (node.children != null && node.children.length > 0) parseChildren(node.children, item);
		        }
		        
		        var currentY = PADDING;
		        for (var j = 0; j < rootItemsList.length; j++) {
		            var rItem = rootItemsList[j];
		            rItem.updateSize(maxRootWidth); 
		            rItem.x = PADDING;
		            rItem.y = currentY;
		            currentY += rItem.actualHeight + ITEM_GAP; 
		        }
		
		        // TỰ ĐỘNG VẼ NỀN TRẮNG CHO MENU CẤP 1
		        var panelW = maxRootWidth + (PADDING * 2);
		        var panelH = currentY + PADDING - ITEM_GAP;
		
		        var bgRoot = new createjs.Shape();
		        bgRoot.graphics.beginFill("#FFFFFF")
		              .setStrokeStyle(1).beginStroke("rgba(75,85,99,0.2)")
		              .drawRoundRect(0, 0, panelW, panelH, 6, 6)
		              .endFill().endStroke();
		              
		        container.addChildAt(bgRoot, 0); // Đẩy tấm nền xuống dưới cùng
		    }
		
		    function parseChildren(childrenData, parentItem) {
		        for (var i = 0; i < childrenData.length; i++) {
		            var node = childrenData[i];
		            var childItem = createMenuItem(node.label, node.action ? node.action : "");
		            parentItem.addSubItem(childItem);
		            if (node.children != null && node.children.length > 0) parseChildren(node.children, childItem);
		        }
		    }
		
		    // =============================================================
		    // 3. KHỞI TẠO CONTANIER (CHƯA VẼ DATA VỘI)
		    // =============================================================
		    var menuBar = new createjs.Container();
		    menuBar.name = "menuBar"; 
		    _this.addChild(menuBar); 
		    window.menuBarRoot = menuBar; 
		    
		    var isMenuBuilt = false; // CỜ ĐÁNH DẤU: Tình trạng chưa vẽ Menu
		
		    // =============================================================
		    // 4. LOGIC BẬT/TẮT & BƠM DỮ LIỆU ĐỘNG (LAZY LOAD)
		    // =============================================================
		    menuBar.visible = false; 
		
		    // Dò tìm nút Menu thông minh
		    var menuBtn = null;
		    if (typeof resolvePath === "function") {
		        menuBtn = resolvePath("menuBtn") || resolvePath("btn_menu") || resolvePath("tombol_menu");
		    }
		    if (!menuBtn) {
		        menuBtn = _this.getChildByName("menuBtn") || _this.getChildByName("btn_menu") || _this.menuBtn;
		    }
		
		    if (menuBtn != null) {
		        menuBtn.name = "menuBtn"; 
		        menuBtn.removeAllEventListeners("click");
		        menuBtn.cursor = "pointer";
		        menuBtn.on("click", onToggleMenuClick);
		    } else {
		        menuBar.x = 100;
		        menuBar.y = 50;
		    }
		
		    function onToggleMenuClick(e) {
		        e.nativeEvent.stopPropagation(); 
		        e.stopPropagation(); 
		        
		        // 🔥 GIẢI PHÁP TỐI THƯỢNG: Chỉ vẽ Menu khi bấm lần đầu tiên
		        // Lúc này đảm bảo 100% file Python đã nạp xong dữ liệu
		        if (!isMenuBuilt) {
		            var sData = window.ScenarioData || (typeof exportRoot !== "undefined" ? exportRoot.ScenarioData : null);
		            if (sData && sData.menuTree) {
		                buildMenu(sData.menuTree, menuBar);
		                isMenuBuilt = true;
		                console.log("✅ Đã lấy Data Python và Vẽ giao diện Menu thành công!");
		            } else {
		                console.warn("⚠️ Bấm mở rồi mà vẫn chưa thấy dữ liệu menuTree đâu!");
		            }
		        }
		
		        menuBar.visible = !menuBar.visible;
		
		        if (menuBar.visible) {
		            // Căn chỉnh tọa độ
		            var btnBounds = menuBtn.nominalBounds || menuBtn.getBounds();
		            if (btnBounds) {
		                var pt = menuBtn.localToGlobal(btnBounds.x + btnBounds.width, btnBounds.y);
		                var localPt = _this.globalToLocal(pt.x, pt.y);
		                menuBar.x = localPt.x + 15; 
		                menuBar.y = localPt.y; 
		            } else {
		                menuBar.x = menuBtn.x + 50;
		                menuBar.y = menuBtn.y;
		            }
		            
		            _this.setChildIndex(menuBar, _this.numChildren - 1);
		        } else {
		            closeAllSubMenus();
		        }
		    }
		
		    // CLICK-AWAY: Đóng menu khi click ra ngoài
		    if (_this.stage) {
		        _this.stage.on("stagemousedown", onStageClickToClose);
		    }
		
		    function onStageClickToClose(e) {
		        if (menuBar.visible) {
		            var clickedObj = e.target;
		            var isInsideMenu = false;
		            
		            var temp = clickedObj;
		            while (temp != null) {
		                if (temp === menuBar || temp === menuBtn) {
		                    isInsideMenu = true;
		                    break;
		                }
		                if (temp === _this.stage) break;
		                temp = temp.parent;
		            }
		            
		            if (!isInsideMenu) {
		                menuBar.visible = false;
		                closeAllSubMenus();
		            }
		        }
		    }
		
		    function closeAllSubMenus() {
		        if (typeof rootItemsList !== "undefined") {
		            for (var i = 0; i < rootItemsList.length; i++) {
		                if (rootItemsList[i] && typeof rootItemsList[i].closeEntireTree === "function") {
		                    rootItemsList[i].closeEntireTree();
		                }
		            }
		        }
		    }
		}
