		// =====================================================================
		// 1. TẠO CỬA SỔ ĐỒ THỊ (DRAGGABLE & LUÔN NỔI LÊN TRÊN CÙNG)
		// =====================================================================
		var graphWindow:Sprite = new Sprite();
		addChild(graphWindow);
		graphWindow.x = 50; 
		graphWindow.y = 50;
		graphWindow.visible = false; 
		
		// Nền cửa sổ giả lập giấy kỹ thuật
		graphWindow.graphics.beginFill(0x1A1C23, 0.95);
		graphWindow.graphics.lineStyle(2, 0x3D445C);
