		legendBox.graphics.moveTo(0, 10); legendBox.graphics.lineTo(30, 10);
		var txtL:TextField = new TextField(); txtL.text = "Động cơ Trái"; txtL.textColor = 0xFFFFFF; txtL.x = 35; txtL.y = 2; txtL.width = 100;
