		addEventListener(Event.ENTER_FRAME, plotGraphEngine);
		
		// Hàm đọc chỉ số vòng quay từ UI (Vẫn giữ nguyên để bắt chế độ MG, 0.3, 0.7, Max)
		function docDongHoVongQuay(dongHo:MovieClip):Number {
			if (!dongHo) return 0;
			var txtStr:String = "0";
			if (dongHo.vongQuay_txt_2 && dongHo.vongQuay_txt_2.visible && dongHo.vongQuay_txt_2.text != "") {
				txtStr = dongHo.vongQuay_txt_2.text; 
			} else if (dongHo.vongQuay_txt_1 && dongHo.vongQuay_txt_1.visible && dongHo.vongQuay_txt_1.text != "") {
				txtStr = dongHo.vongQuay_txt_1.text; 
			} else if (dongHo.vongQuay_txt && dongHo.vongQuay_txt.visible && dongHo.vongQuay_txt.text != "") {
				txtStr = dongHo.vongQuay_txt.text;   
			}
			txtStr = txtStr.replace(",", "."); 
			var val:Number = parseFloat(txtStr);
			return isNaN(val) ? 0 : val;
		}
		
		function getActualRPM_Left():Number {
			try {
				if (typeof manHinhChinh !== "undefined" && manHinhChinh) {
					if (manHinhChinh.manHinhTrai && manHinhChinh.manHinhTrai.dongHoVongQuayTrai) return docDongHoVongQuay(manHinhChinh.manHinhTrai.dongHoVongQuayTrai);
					if (manHinhChinh.manHinhGiua && manHinhChinh.manHinhGiua.dongHoVongQuayTrai) return docDongHoVongQuay(manHinhChinh.manHinhGiua.dongHoVongQuayTrai);
					if (manHinhChinh.manHinhPhai && manHinhChinh.manHinhPhai.dongHoVongQuayTrai) return docDongHoVongQuay(manHinhChinh.manHinhPhai.dongHoVongQuayTrai);
				}
			} catch (e:Error) {}
			return 0;
		}
		
		function getActualRPM_Right():Number {
			try {
				if (typeof manHinhChinh !== "undefined" && manHinhChinh) {
					if (manHinhChinh.manHinhTrai && manHinhChinh.manHinhTrai.dongHoVongQuayPhai) return docDongHoVongQuay(manHinhChinh.manHinhTrai.dongHoVongQuayPhai);
					if (manHinhChinh.manHinhGiua && manHinhChinh.manHinhGiua.dongHoVongQuayPhai) return docDongHoVongQuay(manHinhChinh.manHinhGiua.dongHoVongQuayPhai);
					if (manHinhChinh.manHinhPhai && manHinhChinh.manHinhPhai.dongHoVongQuayPhai) return docDongHoVongQuay(manHinhChinh.manHinhPhai.dongHoVongQuayPhai);
				}
			} catch (e:Error) {}
			return 0;
		}
		
		function plotGraphEngine(e:Event):void {
			var rpmLeft:Number = getActualRPM_Left();
			var rpmRight:Number = getActualRPM_Right();
		
			// KÍCH HOẠT GHI TỰ ĐỘNG: Ngay khi phát hiện 1 trong 2 máy bắt đầu tăng tua (> 0)
			if (!isRecording && (rpmLeft > 0 || rpmRight > 0)) {
				isRecording = true;
				graphStartTime = getTimer(); // Chốt mốc mili-giây ban đầu của hệ thống làm điểm 0
			}
		
			if (!isRecording) return;
		
			// CÔNG THỨC ĐẾM THỜI GIAN THEO LOGIC TOÁN HỌC (Thay thế hoàn toàn việc quét text)
			// Lấy số mili-giây thực tế chạy được chia cho 1000 để ra số giây siêu chuẩn xác
			time_sec = (getTimer() - graphStartTime) / 1000;
		
			var mappedY_Left:Number = getMapY(rpmLeft);
			var mappedY_Right:Number = getMapY(rpmRight);
			var baseX:Number = time_sec * SPEED_X;
		
			// Lưu điểm vẽ vào bộ nhớ nền
			if (plotDataLeft.length == 0 || plotDataLeft[plotDataLeft.length - 1].x != baseX) {
				plotDataLeft.push({x: baseX, y: mappedY_Left});
				plotDataRight.push({x: baseX, y: mappedY_Right});
			}
		
			// TỰ ĐỘNG ÉP TRỤC X KHI CHẠM MÉP PHẢI (780px)
			if (baseX * scaleX_factor > 780) {
				scaleX_factor *= 0.7; // Thu nhỏ trục X lại 30%
				drawDynamicXGrid();   // Lệnh cho lưới trục X cập nhật lại thang đo thời gian mới
			}
		
			// TIẾP TỤC GHI NGẦM - CHỈ RENDER HÌNH ẢNH KHI NGƯỜI DÙNG MỞ CỬA SỔ
			if (!graphWindow.visible) return;
		
			// Vẽ Động cơ Trái (Xanh)
			lineLayerLeft.graphics.clear();
			lineLayerLeft.graphics.lineStyle(3, 0x00A2E8, 1); 
			if (plotDataLeft.length > 0) {
				lineLayerLeft.graphics.moveTo(plotDataLeft[0].x * scaleX_factor, plotDataLeft[0].y);
				for (var i:int = 1; i < plotDataLeft.length; i++) lineLayerLeft.graphics.lineTo(plotDataLeft[i].x * scaleX_factor, plotDataLeft[i].y);
			}
		
			// Vẽ Động cơ Phải (Cam)
			lineLayerRight.graphics.clear();
			lineLayerRight.graphics.lineStyle(3, 0xFF9800, 0.9);
			if (plotDataRight.length > 0) {
				lineLayerRight.graphics.moveTo(plotDataRight[0].x * scaleX_factor, plotDataRight[0].y);
				for (var j:int = 1; j < plotDataRight.length; j++) lineLayerRight.graphics.lineTo(plotDataRight[j].x * scaleX_factor, plotDataRight[j].y);
			}
		}
		
		// =====================================================================
		// 4. GẮN NÚT VẬT LÝ MỞ ĐỒ THỊ
