		// Đảm bảo code chỉ khởi tạo 1 lần trên Timeline HTML5
		if (!this.isPanelStateInitialized) {
		    this.isPanelStateInitialized = true;
		    var _this = this;
		
		    // =============================================================
		    // 1. CẤU HÌNH & TRẠNG THÁI NGUỒN
		    // =============================================================
		    var tt = {
		        rerum_lev: true, rerum_prav: true, 
		        akum_lev: true, akum_prav: true, 
		        gen_lev: true, gen_prav: true, gen_vcy: true, 
		        topl: true, oxy: true, 
		        nap_vcy: true, nap_dc: true 
		    };
		
		    var akum_lev_code = 1;
		    var akum_prav_code = 1;
		    var gen_lev_active = 1; // 1 = Tắt, 0 = Bật
		    var gen_prav_active = 1;
		
		    // =============================================================
		    // 2. HÀM XỬ LÝ CHUNG
		    // =============================================================
		    function toggleSwitch(btn, key) {
		        try { 
		            createjs.Sound.play("Sound_CongTacClass"); 
		        } catch(e) {} 
		        
		        tt[key] = !tt[key]; 
		        return tt[key]; 
		    }
		
		    function safeResetTimers() {
		        try {
		            var timers = [
		                _this.myTimer_DC1_Trai, _this.myTimer_DC2_Trai, _this.myTimer_DC3_Trai, _this.myTimer_DC4_Trai, _this.myTimer_DC5_Trai,
		                _this.myTimer_DC1_Phai, _this.myTimer_DC2_Phai, _this.myTimer_DC3_Phai, _this.myTimer_DC4_Phai, _this.myTimer_DC5_Phai
		            ];
		            for (var i = 0; i < timers.length; i++) {
		                var t = timers[i];
		                if (t && typeof t.reset === "function") t.reset();
		            }
		        } catch(e) {}
		    }
		
		    function setChildFrame(parentMC, childName, frame) {
		        var child = parentMC.getChildByName(childName) || parentMC[childName]; 
		        if (child && typeof child.gotoAndStop === "function") {
		            if (child.currentFrame !== frame) child.gotoAndStop(frame);
		        }
		    }
		
		    function updateScreenVisibility() {
		        var isPowered = (akum_lev_code === 0 || akum_prav_code === 0 || gen_lev_active === 0 || gen_prav_active === 0);
		        var mainScr = _this.manHinhChinh;
		        if (!mainScr) return;
		
		        if (isPowered) {
		            if (mainScr.manHinhTrai && mainScr.manHinhTrai.currentFrame === 0) { 
		                mainScr.manHinhTrai.gotoAndStop(20); 
		                bindScreenButtons(mainScr.manHinhTrai); 
		            }
		            if (mainScr.manHinhGiua && mainScr.manHinhGiua.currentFrame === 0) { 
		                mainScr.manHinhGiua.gotoAndStop(7);  
		                bindScreenButtons(mainScr.manHinhGiua); 
		            }
		            if (mainScr.manHinhPhai && mainScr.manHinhPhai.currentFrame === 0) { 
		                mainScr.manHinhPhai.gotoAndStop(3);  
		                bindScreenButtons(mainScr.manHinhPhai); 
		            }
		        } else {
		            if (mainScr.manHinhTrai) { mainScr.manHinhTrai.gotoAndStop(0); mainScr.manHinhTrai.isBound = false; }
		            if (mainScr.manHinhGiua) { mainScr.manHinhGiua.gotoAndStop(0); mainScr.manHinhGiua.isBound = false; }
		            if (mainScr.manHinhPhai) { mainScr.manHinhPhai.gotoAndStop(0); mainScr.manHinhPhai.isBound = false; }
		        }
		    }
		
		    // =============================================================
		    // 3. ĐỒNG BỘ TRẠNG THÁI KHUNG HÌNH LIÊN TỤC
		    // =============================================================
		    function syncVisualsLoop(e) {
		        var nnl = _this.nguonNangLuong ? _this.nguonNangLuong.congTacNguon : null;
		        if (nnl) {
		            setChildFrame(nnl, "akum_lev", tt.akum_lev ? 0 : 1);
		            setChildFrame(nnl, "akum_prav", tt.akum_prav ? 0 : 1);
		            setChildFrame(nnl, "generator_lev", tt.gen_lev ? 0 : 1);
		            setChildFrame(nnl, "generator_prav", tt.gen_prav ? 0 : 1);
		            setChildFrame(nnl, "generator_vcy", tt.gen_vcy ? 0 : 1);
		            setChildFrame(nnl, "topl_nasos", tt.topl ? 0 : 1);
		            setChildFrame(nnl, "kislorod_oxy", tt.oxy ? 0 : 1);
		        }
		
		        var spr = _this.manHinhChinh ? _this.manHinhChinh.small_panel_right : null;
		        if (spr) {
		            setChildFrame(spr, "rerum_zapus_lev", tt.rerum_lev ? 0 : 1);
		            setChildFrame(spr, "rerum_zapus_prav", tt.rerum_prav ? 0 : 1);
		            setChildFrame(spr, "napAnKD_VCY", tt.nap_vcy ? 0 : 1);
		            setChildFrame(spr, "napAnKD_DC", tt.nap_dc ? 0 : 1);
		        }
		
		        var mainScr = _this.manHinhChinh;
		        if (mainScr) {
		            var screens = [mainScr.manHinhTrai, mainScr.manHinhGiua, mainScr.manHinhPhai];
		            for (var i = 0; i < screens.length; i++) {
		                var s = screens[i];
		                if (!s) continue;
		                
		                if (s.currentFrame === 7) { 
		                    setChildFrame(s, "mayPhat_DC_Trai", tt.gen_lev ? 0 : 1);
		                    setChildFrame(s, "mayPhat_DC_Phai", tt.gen_prav ? 0 : 1);
		                    setChildFrame(s, "mayPhat_VCY",   tt.gen_vcy ? 0 : 1);
		                }
		                if (s.currentFrame === 4) { 
		                    setChildFrame(s, "bomNLDay", tt.topl ? 0 : 1);
		                    setChildFrame(s, "bomNLKD",  tt.topl ? 0 : 1);
		                }
		            }
		        }
		    }
		    createjs.Ticker.addEventListener("tick", syncVisualsLoop); 
		
		    // =============================================================
		    // 4. LOGIC MÀN HÌNH (STATE MACHINE)
		    // =============================================================
		    function bindScreenButtons(mc) {
		        if (!mc || mc.isBound) return; 
		        mc.isBound = true; 
		
		        if (isNaN(mc.fotoAktif)) mc.fotoAktif = 1; 
		        if (isNaN(mc.stepFrame)) mc.stepFrame = 20; 
		
		        var lastClickTime = 0;
		        if (!mc.eventTracker) mc.eventTracker = {};
		
		        function getMC(name) { return mc[name] || mc.getChildByName(name); }
		
		        function bindClick(btnName, newFunc) {
		            var btn = getMC(btnName);
		            if (!btn) return;
		            if (mc.eventTracker[btnName] != null) {
		                btn.off("click", mc.eventTracker[btnName]);
		            }
		            btn.cursor = "pointer";
		            btn.mouseChildren = false; 
		            mc.eventTracker[btnName] = btn.on("click", newFunc);
		        }
		
		        function unbindClick(btnName) {
		            var btn = getMC(btnName);
		            if (!btn) return;
		            if (mc.eventTracker[btnName] != null) {
		                btn.off("click", mc.eventTracker[btnName]);
		                delete mc.eventTracker[btnName];
		            }
		        }
		
		        function unbindAllDynamic() {
		            unbindClick("btn_dvig"); unbindClick("btn_topl"); unbindClick("btn_gidr");
		            unbindClick("btn_czo");  unbindClick("btn_cec");  unbindClick("btn_kcy");
		            unbindClick("btn_avtk"); unbindClick("btn_vuxd"); unbindClick("btn_lev");
		        }
		
		        function onKissClick(e) { enterMenuChinh(); }
		        function onPilClick(e)  { unbindAllDynamic(); mc.gotoAndStop(34); } 
		        function onNvgClick(e)  { unbindAllDynamic(); mc.gotoAndStop(35); } 
		        function onItoClick(e)  { unbindAllDynamic(); mc.gotoAndStop(36); } 
		        
		        function onBaskClick(e) { 
		            var currentParent = e.target;
		            var parentScreen = null;
		            var mainScr = _this.manHinhChinh;
		            
		            while (currentParent != null && currentParent !== _this.stage) {
		                if (mainScr && (currentParent === mainScr.manHinhTrai || currentParent === mainScr.manHinhGiua || currentParent === mainScr.manHinhPhai)) {
		                    parentScreen = currentParent; break;
		                }
		                currentParent = currentParent.parent;
		            }
		
		            if (parentScreen != null && parentScreen.currentFrame === 1) return; 
		            enterTruocBay(); 
		        }
		
		        function refreshMenuButtons() {
		            setTimeout(function() {
		                bindClick("btn_dvig", onDvigMenu);
		                bindClick("btn_topl", onToplMenu);
		                bindClick("btn_gidr", onGidrMenu);
		                bindClick("btn_czo", onCzoMenu);
		                bindClick("btn_cec", onCecMenu);
		                bindClick("btn_kcy", onKcyMenu);
		            }, 20); 
		        }
		
		        function onDvigMenu(e) { mc.gotoAndStop(1); refreshMenuButtons(); } 
		        function onToplMenu(e) { mc.gotoAndStop(4); refreshMenuButtons(); } 
		        function onGidrMenu(e) { mc.gotoAndStop(5); refreshMenuButtons(); } 
		        function onCzoMenu(e)  { mc.gotoAndStop(6); refreshMenuButtons(); } 
		        function onCecMenu(e)  { mc.gotoAndStop(7); refreshMenuButtons(); } 
		        function onKcyMenu(e)  { mc.gotoAndStop(8); refreshMenuButtons(); } 
		
		        function onDvigStep(e) { stepDvig(); }
		        function onAvtkClick(e){ enterGallery(); }
		        
		        function onKcyNext(e) {
		            if (e.nativeEvent) e.nativeEvent.stopPropagation();
		            var now = new Date().getTime();
		            if (now - lastClickTime < 200) return; 
		            lastClickTime = now;
		            var scroll_avtk = getMC("scroll_avtk");
		            if (scroll_avtk) {
		                var nextF = scroll_avtk.currentFrame + 1;
		                if (nextF >= scroll_avtk.totalFrames) nextF = 0; 
		                scroll_avtk.gotoAndStop(nextF); 
		            }
		        }
		
		        function onCecPrev(e) {
		            if (e.nativeEvent) e.nativeEvent.stopPropagation();
		            var now = new Date().getTime();
		            if (now - lastClickTime < 200) return; 
		            lastClickTime = now;
		            var scroll_avtk = getMC("scroll_avtk");
		            if (scroll_avtk) {
		                var prevF = scroll_avtk.currentFrame - 1;
		                if (prevF < 0) prevF = scroll_avtk.totalFrames - 1;
		                scroll_avtk.gotoAndStop(prevF); 
		            }
		        }
		        
		        function onCzoDetail(e) { enterDetailMode(); }
		        function onVuxdBack(e)  { enterGallery(); }
		        
		        function onGidrDetail(e) {
		            mc.gotoAndStop(18); 
		            unbindAllDynamic(); 
		            bindClick("btn_vuxd", onVuxdBack); 
		            bindClick("btn_lev", onLevDetail); 
		        }
		        
		        function onLevDetail(e) {
		            mc.gotoAndStop(17); 
		            unbindAllDynamic(); 
		            bindClick("btn_vuxd", onVuxdBack); 
		            bindClick("btn_gidr", onGidrDetail); 
		        }
		
		        bindClick("btn_kiss", onKissClick);
		        bindClick("btn_pil", onPilClick);
		        bindClick("btn_nvg", onNvgClick);
		        bindClick("btn_ito", onItoClick);
		        bindClick("btn_bask", onBaskClick);
		
		        function enterMenuChinh() {
		            mc.gotoAndStop(3); 
		            unbindAllDynamic(); 
		            refreshMenuButtons(); 
		        }
		
		        function enterTruocBay() {
		            mc.stepFrame = 20; 
		            mc.gotoAndStop(20); 
		            var scroll_avtk = getMC("scroll_avtk");
		            if(scroll_avtk) scroll_avtk.gotoAndStop(0);
		
		            unbindAllDynamic();
		            bindClick("btn_dvig", onDvigStep);
		            bindClick("btn_avtk", onAvtkClick);
		        }
		
		        function stepDvig() {
		            var s = mc.stepFrame;
		            if (s >= 20 && s <= 30) { 
		                var nextFrame = s + 1;
		                mc.gotoAndStop(nextFrame);
		                
		                var mainScr = _this.manHinhChinh;
		                if (nextFrame === 22) { 
		                    if(mainScr && mainScr.manHinhGiua) mainScr.manHinhGiua.gotoAndStop(1);
		                } 
		                else if (nextFrame === 27) { 
		                    if(mainScr && mainScr.manHinhGiua) mainScr.manHinhGiua.gotoAndStop(32); 
		                } 
		                else if (nextFrame === 28) { 
		                    if(mainScr && mainScr.manHinhGiua) mainScr.manHinhGiua.gotoAndStop(1);
		                }
		                mc.stepFrame = nextFrame;
		            }
		        }
		
		        function enterGallery() {
		            mc.gotoAndStop(15); 
		            unbindAllDynamic();
		            
		            setTimeout(function() {
		                var scroll_avtk = getMC("scroll_avtk");
		                if(scroll_avtk) { scroll_avtk.visible = true; scroll_avtk.gotoAndStop(0); }
		                bindClick("btn_kcy", onKcyNext);
		                bindClick("btn_cec", onCecPrev);
		                bindClick("btn_czo", onCzoDetail);
		            }, 20);
		        }
		
		        function enterDetailMode() {
		            var scroll_avtk = getMC("scroll_avtk");
		            if(!scroll_avtk) return;
		            var f = scroll_avtk.currentFrame;
		            
		            scroll_avtk.visible = false;
		            
		            if (f === 14) { mc.gotoAndStop(16); } 
		            else if (f === 15) { mc.gotoAndStop(17); } 
		            else if (f === 16) { mc.gotoAndStop(18); } 
		            else { scroll_avtk.visible = true; return; }
		
		            unbindAllDynamic(); 
		            bindClick("btn_vuxd", onVuxdBack);
		
		            if (mc.currentFrame === 17) bindClick("btn_gidr", onGidrDetail);
		            else if (mc.currentFrame === 18) bindClick("btn_lev", onLevDetail);
		        }
		
		        if (mc.currentFrame === 20 || mc.currentFrame === 3) {
		            if (mc.currentFrame === 20) enterTruocBay();
		            if (mc.currentFrame === 3) enterMenuChinh();
		        }
		    }
		
		    // =============================================================
		    // 5. XỬ LÝ NGUỒN PIN VÀ NÚT TƯƠNG TÁC (CHỈ BẮT SỰ KIỆN CLICK)
		    // =============================================================
		    function setupAkum(btn, key) {
		        if(!btn) return;
		        btn.on("click", function(e) {
		            var isOff = toggleSwitch(btn, key); 
		            if (isOff) { 
		                try { if (_this.stopVCY) _this.stopVCY.gotoAndStop(0); } catch (err) {} 
		                if (key === "akum_lev") akum_lev_code = 1; else akum_prav_code = 1;
		                safeResetTimers();
		            } else { 
		                if (key === "akum_lev") akum_lev_code = 0; else akum_prav_code = 0;
		            }
		            updateScreenVisibility(); 
		        });
		    }
		
		    function onRerumClick(e) {
		        var btn = e.currentTarget;
		        var spr = _this.manHinhChinh && _this.manHinhChinh.small_panel_right;
		        var key = (spr && btn === spr.rerum_zapus_lev) ? "rerum_lev" : "rerum_prav";
		        toggleSwitch(btn, key);
		    }
		
		    function onGenClick(e) {
		        var btn = e.currentTarget;
		        var nnl = _this.nguonNangLuong && _this.nguonNangLuong.congTacNguon;
		        if(!nnl) return;
		        var key = (btn === nnl.generator_lev) ? "gen_lev" : (btn === nnl.generator_prav) ? "gen_prav" : "gen_vcy";
		                         
		        var isOff = toggleSwitch(btn, key); 
		        
		        if (key === "gen_lev") gen_lev_active = isOff ? 1 : 0;
		        if (key === "gen_prav") gen_prav_active = isOff ? 1 : 0;
		        
		        updateScreenVisibility();
		    }
		
		    function onNapClick(e) {
		        var btn = e.currentTarget;
		        var spr = _this.manHinhChinh && _this.manHinhChinh.small_panel_right;
		        if(!spr) return;
		
		        var isVCY = (btn === spr.napAnKD_VCY);
		        var key = isVCY ? "nap_vcy" : "nap_dc";
		        var isOff = toggleSwitch(btn, key);
		        
		        if (isVCY) {
		            if(spr.nutAnKD_VCY) spr.nutAnKD_VCY.visible = !isOff;
		        } else {
		            var v = !isOff;
		            if(spr.nutAnKD_DC) spr.nutAnKD_DC.visible = v;
		            if(spr.nutAnKD_DC_Trai) spr.nutAnKD_DC_Trai.visible = v;
		            if(spr.nutAnKD_DC_Phai) spr.nutAnKD_DC_Phai.visible = v;
		        }
		    }
		
		    // =============================================================
		    // 6. KHỞI TẠO ĐÈN CẢNH BÁO
		    // =============================================================
		    function xuLycacNutCanhBao() {
		        var mainScr = _this.manHinhChinh;
		        if(!mainScr) return;
		
		        var lights = [
		            mainScr.denBaoHongTapTrung, mainScr.denBaoHong_CDY, mainScr.denBaoHong_Gidr, 
		            mainScr.pajar_kran_lev ? mainScr.pajar_kran_lev.pajar_lamp_lev : null,
		            mainScr.pajar_kran_lev ? mainScr.pajar_kran_lev.pajar_kran_lev : null,
		            mainScr.pajar_kran_prav ? mainScr.pajar_kran_prav.pajar_lamp_prav : null,
		            mainScr.pajar_kran_prav ? mainScr.pajar_kran_prav.pajar_kran_prav : null,
		            mainScr.small_panel_right ? mainScr.small_panel_right.dapLua_BCY : null
		        ];
		
		        for (var i = 0; i < lights.length; i++) { if(lights[i]) lights[i].gotoAndStop(0); }
		
		        if (mainScr.kontron_lamp) {
		            mainScr.kontron_lamp.cursor = "pointer";
		            // Đối với đèn nhấn giữ thì dùng mousedown/pressup là bắt buộc
		            mainScr.kontron_lamp.on("mousedown", function(e) { 
		                for (var j = 0; j < lights.length; j++) { if(lights[j]) lights[j].play(); } 
		            });
		            mainScr.kontron_lamp.on("pressup", function(e) { 
		                for (var k = 0; k < lights.length; k++) { if(lights[k]) lights[k].gotoAndStop(0); } 
		            });
		        }
		    }
		
		    // Gán biến và khóa trẻ em (mouseChildren) để bảo vệ click
		    var nnl = _this.nguonNangLuong ? _this.nguonNangLuong.congTacNguon : null;
		    var spr = _this.manHinhChinh ? _this.manHinhChinh.small_panel_right : null;
		
		    var initObjects = [];
		    if(spr) initObjects.push(spr.rerum_zapus_lev, spr.rerum_zapus_prav, spr.napAnKD_VCY, spr.napAnKD_DC);
		    if(nnl) initObjects.push(nnl.akum_lev, nnl.akum_prav, nnl.generator_lev, nnl.generator_prav, nnl.generator_vcy, nnl.kislorod_oxy, nnl.topl_nasos);
		
		    for (var m = 0; m < initObjects.length; m++) { 
		        var obj = initObjects[m];
		        if (obj) { 
		            obj.mouseChildren = false; // CHỐNG LIỆT CLICK TUYỆT ĐỐI
		            obj.cursor = "pointer"; 
		        } 
		    }
		
		    var hiddenBtns = [];
		    if(spr) hiddenBtns.push(spr.nutAnKD_VCY, spr.nutAnKD_DC, spr.nutAnKD_DC_Trai, spr.nutAnKD_DC_Phai, spr.nutAnKD_VCY_2DC, spr.nutAnKD_2DC);
		    for (var n = 0; n < hiddenBtns.length; n++) { 
		        if(hiddenBtns[n]) hiddenBtns[n].visible = false; 
		    }
		
		    if (_this.manHinhChinh) {
		        if (_this.manHinhChinh.manHinhTrai) _this.manHinhChinh.manHinhTrai.gotoAndStop(0);
		        if (_this.manHinhChinh.manHinhGiua) _this.manHinhChinh.manHinhGiua.gotoAndStop(0);
		        if (_this.manHinhChinh.manHinhPhai) _this.manHinhChinh.manHinhPhai.gotoAndStop(0);
		    }
		
		    // Gắn sự kiện (CHỈ DÙNG CLICK - TRỊ BỆNH NHÁY ĐÚP VÀ KÊU 2 LẦN)
		    if(spr && spr.rerum_zapus_lev) spr.rerum_zapus_lev.on("click", onRerumClick);
		    if(spr && spr.rerum_zapus_prav) spr.rerum_zapus_prav.on("click", onRerumClick);
		    if(nnl && nnl.akum_lev) setupAkum(nnl.akum_lev, "akum_lev");
		    if(nnl && nnl.akum_prav) setupAkum(nnl.akum_prav, "akum_prav");
		    if(nnl && nnl.generator_lev) nnl.generator_lev.on("click", onGenClick);
		    if(nnl && nnl.generator_prav) nnl.generator_prav.on("click", onGenClick);
		    if(nnl && nnl.generator_vcy) nnl.generator_vcy.on("click", onGenClick);
		    
		    if(nnl && nnl.topl_nasos) nnl.topl_nasos.on("click", function(e) { toggleSwitch(e.currentTarget, "topl"); });
		    if(nnl && nnl.kislorod_oxy) nnl.kislorod_oxy.on("click", function(e) { toggleSwitch(e.currentTarget, "oxy"); });
		    if(spr && spr.napAnKD_VCY) spr.napAnKD_VCY.on("click", onNapClick);
		    if(spr && spr.napAnKD_DC) spr.napAnKD_DC.on("click", onNapClick);
		
		    xuLycacNutCanhBao();
		}
